dashboard.definition:
{
  "title": "HANA Audit",
  "description": "SAP HANA audit log analysis — user activity, failed operations, risk-tiered events, and after-hours access patterns",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Audit Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_failures": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_failures"
      },
      "title": "Failed Operations",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_users": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_users"
      },
      "title": "Active Users",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_2nZCdB19": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_1ZmrypYh"
      },
      "options": {
        "backgroundColor": "transparent",
        "x": "> primary | seriesByName('_time')",
        "xAxisTitleVisibility": "hide",
        "resultLimit": 500000,
        "columnSpacing": 0,
        "showSplitSeries": true,
        "columnGrouping": "overlay",
        "showIndependentYRanges": true,
        "yAxisTitleVisibility": "hide",
        "y2AxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "User Administration Activity Timeline",
      "type": "splunk.column"
    },
    "viz_8cdxDtFu": {
      "dataSources": {
        "primary": "ds_yE9yBtpa"
      },
      "title": "Daily Security Health Score",
      "type": "splunk.column",
      "containerOptions": {},
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "daily_events": "#7B56DB",
          "active_users": "#009CEB",
          "daily_failures": "#dc4e41",
          "success_rate": "#53a051"
        },
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_JQwHPBuw": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_Kj5JGWVb": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_UBrqm3dh": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_YIm9coVY": {
      "dataSources": {
        "primary": "ds_pYyp9bI7"
      },
      "title": "Audit Category Breakdown",
      "type": "splunk.pie",
      "containerOptions": {},
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "collapseLabel": "",
        "backgroundColor": "transparent",
        "collapseThreshold": 0
      }
    },
    "viz_aHaxUdSn": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_TsZBieYG"
      },
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "showSplitSeries": true,
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Failed Operation": "#dc4e41",
          "Object Modification": "#62b3b2",
          "Permission Grant": "#f1813f"
        },
        "showIndependentYRanges": true,
        "xAxisMajorTickVisibility": "show",
        "xAxisLabelVisibility": "show",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Security Events Timeline",
      "type": "splunk.column"
    },
    "viz_kxbrvLhz": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_mEe7x9fI": {
      "dataSources": {
        "primary": "ds_WaZCTDkV"
      },
      "title": "Password Management Activities",
      "type": "splunk.table",
      "containerOptions": {},
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerVisibility": "fixed",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520"
      }
    },
    "viz_yfcE62rT": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_4bIlKobW": {
      "dataSources": {
        "primary": "ds_NNjH6XTd_ds_pYyp9bI7"
      },
      "title": "Failed Operations by Host",
      "type": "splunk.pie",
      "containerOptions": {},
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "collapseLabel": "",
        "backgroundColor": "transparent",
        "collapseThreshold": 0
      }
    },
    "viz_AV7emsQq": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_top_users": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_users"
      },
      "title": "Top Users by Activity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_after_hours": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_after_hours"
      },
      "title": "Activity by Hour of Day",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Failures": "#dc4e41",
          "Successes": "#4fa484"
        },
        "dataValuesDisplay": "off"
      }
    },
    "viz_client_ips": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_client_ips"
      },
      "title": "Client IP Analysis",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3m": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_risk_timeline": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_risk_timeline"
      },
      "title": "Risk-Tiered Event Timeline",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off",
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "seriesColorsByField": {
          "critical": "#dc4e41",
          "high": "#f4a535",
          "medium": "#ffcc00",
          "low": "#00d4b4",
          "info": "#7ee8fa"
        }
      }
    },
    "viz_high_risk_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_high_risk_events"
      },
      "title": "High-Risk Events (is_critical=true)",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3Dsap%3Ahana%3Aaudit%20is_critical%3Dtrue%20executing_user%3D%22%24row.User.value%24%22%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_after_hours_admin": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_after_hours_admin"
      },
      "title": "After-Hours / Weekend Admin Activity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3Dsap%3Ahana%3Aaudit%20is_admin_user%3Dtrue%20executing_user%3D%22%24row.User.value%24%22%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_rect_r4l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r4r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r5": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/applications/#hana-audit",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_failures": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit status!=\"SUCCESSFUL\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_users": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit | eventstats dc(executing_user) as window_dc | timechart span=1d dc(executing_user) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_1ZmrypYh": {
      "name": "Column chart search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| where match(audit_category, \"HEC Audit - User Administration\")\r\n| eval admin_action = case(\r\n    match(sql_statement, \"(?i)reset connect\"), \"Password Reset\",\r\n    match(sql_statement, \"(?i)activate user\"), \"User Activation\",\r\n    match(sql_statement, \"(?i)deactivate user\"), \"User Deactivation\",\r\n    match(sql_statement, \"(?i)disable password\"), \"Policy Change\",\r\n    1=1, \"Other Admin\"\r\n)\r\n| timechart span=1d count by admin_action",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_F7WLfuRN_ds_yE9yBtpa": {
      "name": "Bubble chart search copy 1",
      "options": {
        "query": "index=\"sap_logserv_logs\" tag=dns message_type=\"QUERY\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_TsZBieYG": {
      "name": "sec_events_timeline_search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| where status!=\"SUCCESSFUL\" OR match(action_type, \"(?i)(grant|revoke|create|drop)\")\r\n| eval event_type = case(\r\n    status!=\"SUCCESSFUL\", \"Failed Operation\",\r\n    match(action_type, \"(?i)grant\"), \"Permission Grant\",\r\n    match(action_type, \"(?i)revoke\"), \"Permission Revoke\",\r\n    match(action_type, \"(?i)(create|drop)\"), \"Object Modification\",\r\n    1=1, \"Other Security Event\"\r\n)\r\n| timechart span=1d count by event_type",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_WaZCTDkV": {
      "name": "Bubble chart search 2",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| where match(sql_statement, \"(?i)password\")\r\n| eval password_action = case(\r\n    match(sql_statement, \"password \\*\\*\\*\"), \"Password Change\",\r\n    match(sql_statement, \"disable password\"), \"Disable Lifetime\",\r\n    match(sql_statement, \"reset.*connect\"), \"Reset Attempts\",\r\n    1=1, \"Other\"\r\n)\r\n| rename password_action AS Action\r\n| rename target_user AS \"Target User\"\r\n| rename executing_user AS \"Exec User\"\r\n| rename client_ip AS \"Client IP\"\r\n| stats count by Action, \"Target User\", \"Exec User\", \"Client IP\"\r\n| sort -count, Action",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_pYyp9bI7": {
      "name": "Requests by Record Type search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| stats count by action_category\r\n| sort -count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_yE9yBtpa": {
      "name": "Bubble chart search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| eval day = strftime(_time, \"%Y-%m-%d\")\r\n| stats \r\n    count as daily_events,\r\n    dc(executing_user) as active_users,\r\n    sum(eval(if(status!=\"SUCCESSFUL\", 1, 0))) as daily_failures\r\nby day\r\n| eval success_rate = round(((daily_events - daily_failures)/daily_events)*100, 1)\r\n| sort day\r\n| table day, daily_events, active_users, daily_failures, success_rate",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_NNjH6XTd_ds_pYyp9bI7": {
      "name": "Requests by Record Type search copy 1",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit \r\n| where status!=\"SUCCESSFUL\"\r\n| stats count by host\r\n| sort -count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_top_users": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit | stats count as Events dc(action_type) as \"Action Types\" sum(eval(if(status!=\"SUCCESSFUL\",1,0))) as Failures by executing_user | sort -Events | head 20 | rename executing_user as User"
      }
    },
    "ds_after_hours": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit | eval hour=strftime(_time, \"%H\") | eval result=if(status=\"SUCCESSFUL\", \"Successes\", \"Failures\") | chart count over hour by result"
      }
    },
    "ds_client_ips": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit client_ip=* | stats count as Events dc(executing_user) as Users sum(eval(if(status!=\"SUCCESSFUL\",1,0))) as Failures latest(_time) as \"Last Seen\" by client_ip | eval \"Last Seen\"=strftime('Last Seen', \"%Y-%m-%d %H:%M\") | sort -Events | head 20 | rename client_ip as \"Client IP\""
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_risk_timeline": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit risk_level=* | timechart span=1d count by risk_level",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_high_risk_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit is_critical=true | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | sort -_time | head 50 | table Time, executing_user, action_type, action_category, risk_level, status, host, client_ip, sql_statement | rename executing_user as \"User\", action_type as \"Action\", action_category as \"Category\", risk_level as \"Risk Level\", status as \"Status\", host as \"Host\", client_ip as \"Client IP\", sql_statement as \"SQL Statement\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_after_hours_admin": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=sap:hana:audit is_admin_user=true | eval is_weekend=if(strftime(_time,\"%w\") IN (\"0\",\"6\"), 1, 0) | where is_business_hours=false OR is_weekend=1 | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | eval Day=strftime(_time, \"%a\") | eval Hour=strftime(_time, \"%H:%M\") | eval Period=case(is_weekend=1 AND is_business_hours=false, \"Weekend / After Hours\", is_weekend=1, \"Weekend\", 1=1, \"After Hours\") | sort -_time | head 50 | table Time, Day, Period, executing_user, action_type, status, host, client_ip | rename executing_user as \"User\", action_type as \"Action\", status as \"Status\", host as \"Host\", client_ip as \"Client IP\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
